INSERT INTO "emailtemplates" ("id", "TemplateName", "TemplateText", "Subject", "SenderName", "SenderEmail", "AlertChannel", "AlertLanguageCode", "Alert_id") VALUES (2,'activationLink','<p>&nbsp;</p><center><div style=\"width: 95%; height: 5px; margin: 0px 0px 0px 0px;\"><div><table border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\"><tbody><tr><td style=\"background-color: #284e77; font-size: 1px; line-height: 1px; -webkit-text-size-adjust: none;\" align=\"center\" valign=\"top\" bgcolor=\"#284e77\" height=\"10\">&nbsp;</td></tr></tbody></table></div></div><div style=\"width: 95%; margin: 0px 0px 50px 0px;\"><div style=\"display: inline-block; text-align: left;\"><table border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\"><tbody><tr><td style=\"background-color: #ffffff; -webkit-text-size-adjust: none;\"><div style=\"margin: 50px 20px 50px 20px; color: #333b44; font-size: 14px;\"><table style=\"width: 50%;\" width=\"50%\"><tbody><tr><td width=\"200\"><img style=\"text-align: right; width: 200px; border: 0;\" src=\"https://retailbanking1.konycloud.com/dbimages/infinitydbxlogo.png\" alt=\"temenos_logo\" width=\"200\" /></td></tr></tbody></table><br /><br />Hi %userName%,<br /><br />You are invited to Digital Banking Channel. Please activate your account now.<br /> <br /><br />Username: %userName%<br /><br /> <br />You are required to input your Username in the link below.<br /><br /><div style=\"text-align: center; border-width: 1px; border-radius: 4px;\"><table style=\"table-layout: fixed;\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\"><tbody><tr><td style=\"color: #ffffff; background-color: #333b44; word-wrap: break-word; word-break: break-all; padding: 10px; line-height: 20px;\" align=\"center\"><div style=\"margin: 10px 10px 10px 10px; font-size: 13px;\">To activate your account and set a password,<a style=\"color: #11abeb;\" href=\"%resetPasswordLink%\">click here</a> <br /> or paste the following link on your browser: <br /><br /><a style=\"color: #11abeb;\">%resetPasswordLink%</a></div></td></tr></tbody></table></div><br /><div align=\"center\">The link will expire in %linkExpiry% hours, so please use it right away.</div><br />Regards,<br />Temenos Banking Team <br /><br /><br /><br /><span style=\"color: #999999; font-size: 12px;\">This is a system generated mail. If you are not the named addressee please notify the sender immediately by e-mail at support@temenosbank.com and then delete the e-mail from your system. Although the company has taken reasonable precautions to ensure no viruses are present in this email, the company cannot accept responsibility for any loss or damage arising from the use of this email or attachments. Temenos, Inc. www.temenos.com </span><br /><br /><div align=\"center\"><span style=\"color: #999999;\">Copyright &copy; 2020 Infinity DBX. All rights reserved.</span></div></div></td></tr></tbody></table></div></div></center>','Account Activation','kony dbx','retailbankingdemos@kony.com',NULL,NULL,NULL);
