INSERT INTO "emailtemplates" ("id", "TemplateName", "TemplateText", "Subject", "SenderName", "SenderEmail", "AlertChannel", "AlertLanguageCode", "Alert_id") VALUES (20,'BUSINESS_ENROLLMENT_ACTIVATION_TEMPLATE','<!DOCTYPE html><html> <head> <link href=\"http://fonts.googleapis.com/css?family=Lato:400,700\" rel=\"stylesheet\" type=\"text/css\"> <style>body {font-family: \"Lato\";}</style> </head> <body bgcolor= \"#ebecee\"> <center> <div style=\"width:95%; height: 10px; margin: 50px 0px 0px 0px;\"> <div> <table height=\"100%\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"> <!--[if mso]> <center> <tr> <td> <div> <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"95%\"> <![endif]--> <tr> <td align=\"center\" valign=\"top\" height=\"10\" bgcolor=\"#284e77\" style=\"background-color:#284e77;font-size:1px;line-height:1px; -webkit-text-size-adjust:none;\">&nbsp;</td> </tr> </table> <!--[if mso]> </div> </td> </tr> </center> </table> <![endif]--> </div> </div> <div style=\"width:95%; margin: 0px 0px 50px 0px;\"> <div style=\"display: inline-block; text-align: left;\"> <table height=\"100%\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"> <!--[if mso]> <center> <tr> <td> <div> <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"95%\"> <![endif]--> <tr> <td style=\"background-color:#ffffff; -webkit-text-size-adjust:none;\"> <div style=\"margin: 50px 20px 50px 20px; color: #333b44; font-size: 13px;\"> <!--[if mso]> <font face=\"Lato\"> <![endif]--> <span style=\"margin: 10% 0% 5% 0%;\"> <table style=\"width: 50%;\" width=\"50%\"> <tr> <td width=\"200\"> <!--[if mso]> <table width=\"200\"> <tr> <td> <img width=\"200\" src=\"emailTemplateLogo\" alt=\"kony_logo\" style=\"text-align: right; width: 200px; border: 0;\"> </td> </tr> </table> <div style=\"display:none\"> <![endif]--><img style=\"text-align: right; width: 200px; border: 0;\" src=\"https://retailbanking1.konycloud.com/dbimages/infinitydbxlogo.png\" alt=\"temenos_logo\" width=\"200\" /> <!--[if mso]> </div> <![endif]--> </td> <!-- <td style=\"font-size:28px;\">[if mso]> <table height=\"200\"> <tr>&nbsp;</tr> <tr> <td style=\"font-size:28px;\"> &nbsp;BANK </td> </tr> </table> <div style=\"display:none\"> <![endif]&nbsp;BANK [if mso]> </div> <![endif]</td> --> </tr> </table> </span> <br><br><!--[if mso]> <div style=\"margin: -50px 0px 0px 0px;\"> <![endif]-->Hi %firstName% %lastName%,<br><br>Your business banking accounts have been enabled for online banking services. Please contact the bank for more information.<br><br> <br><span>Regards,</span><br><span>Temenos Banking team</span><!-- <br><br><br><span>PS: </span><span style=\"color: #999999;\">We appreciate you might not want these emails, if that\"s the case <a href=\"\" style=\"color: #11abeb;\">click here</a> and you won\"t receive them.</span> --><br><br><br><br><br><br><span style=\"color: #999999;\">This is a system generated mail. If you are not the named addressee please notify the sender immediately by e-mail at support@temenosbank.com and then delete the e-mail from your system. Although the company has taken reasonable precautions to ensure no viruses are present in this email, the company cannot accept responsibility for any loss or damage arising from the use of this email or attachments. Temenos,www.temenos.com</span><br><br> <div align=\"center\"><span style=\"color: #999999;\">Copyright &copy; 2020 Infinity DBX. All rights reserved.</span></div> <!--[if mso]> </div> <![endif]--><!--[if mso]> </font> <![endif]--> </div> </td> </tr> </table> <!--[if mso]> </div> </td> </tr> </center> </table> <![endif]--> </div> </div> </center> </body></html>','Online Banking enabled for your business accounts','Infinity','dbx_cl@infinity.com',NULL,NULL,NULL);
INSERT INTO "emailtemplates" ("id", "TemplateName", "TemplateText", "Subject", "SenderName", "SenderEmail", "AlertChannel", "AlertLanguageCode", "Alert_id") VALUES (21,'BUSINESS_ENROLLMENT_REJECTED_TEMPLATE','<!DOCTYPE html><html> <head> <link href=\"http://fonts.googleapis.com/css?family=Lato:400,700\" rel=\"stylesheet\" type=\"text/css\"> <style>body {font-family: \"Lato\";}</style> </head> <body bgcolor= \"#ebecee\"> <center> <div style=\"width:95%; height: 10px; margin: 50px 0px 0px 0px;\"> <div> <table height=\"100%\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"> <!--[if mso]> <center> <tr> <td> <div> <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"95%\"> <![endif]--> <tr> <td align=\"center\" valign=\"top\" height=\"10\" bgcolor=\"#284e77\" style=\"background-color:#284e77;font-size:1px;line-height:1px; -webkit-text-size-adjust:none;\">&nbsp;</td> </tr> </table> <!--[if mso]> </div> </td> </tr> </center> </table> <![endif]--> </div> </div> <div style=\"width:95%; margin: 0px 0px 50px 0px;\"> <div style=\"display: inline-block; text-align: left;\"> <table height=\"100%\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"> <!--[if mso]> <center> <tr> <td> <div> <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"95%\"> <![endif]--> <tr> <td style=\"background-color:#ffffff; -webkit-text-size-adjust:none;\"> <div style=\"margin: 50px 20px 50px 20px; color: #333b44; font-size: 13px;\"> <!--[if mso]> <font face=\"Lato\"> <![endif]--> <span style=\"margin: 10% 0% 5% 0%;\"> <table style=\"width: 50%;\" width=\"50%\"> <tr> <td width=\"200\"> <!--[if mso]> <table width=\"200\"> <tr> <td> <img width=\"200\" src=\"emailTemplateLogo\" alt=\"kony_logo\" style=\"text-align: right; width: 200px; border: 0;\"> </td> </tr> </table> <div style=\"display:none\"> <![endif]--><img style=\"text-align: right; width: 200px; border: 0;\" src=\"https://retailbanking1.konycloud.com/dbimages/infinitydbxlogo.png\" alt=\"temenos_logo\" width=\"200\" /> <!--[if mso]> </div> <![endif]--> </td> <!-- <td style=\"font-size:28px;\">[if mso]> <table height=\"200\"> <tr>&nbsp;</tr> <tr> <td style=\"font-size:28px;\"> &nbsp;BANK </td> </tr> </table> <div style=\"display:none\"> <![endif]&nbsp;BANK [if mso]> </div> <![endif]</td> --> </tr> </table> </span> <br><br><!--[if mso]> <div style=\"margin: -50px 0px 0px 0px;\"> <![endif]-->Hi %firstName% %lastName% ,<br><br>Your business banking accounts could not be enabled for online banking services. Please contact the bank for more information.<br><br> <br><span>Regards,</span><br><span>Temenos Banking team</span><!-- <br><br><br><span>PS: </span><span style=\"color: #999999;\">We appreciate you might not want these emails, if that\"s the case <a href=\"\" style=\"color: #11abeb;\">click here</a> and you won\"t receive them.</span> --><br><br><br><br><br><br><span style=\"color: #999999;\">This is a system generated mail. If you are not the named addressee please notify the sender immediately by e-mail at support@temenosbank.com and then delete the e-mail from your system. Although the company has taken reasonable precautions to ensure no viruses are present in this email, the company cannot accept responsibility for any loss or damage arising from the use of this email or attachments. Temenos,www.temenos.com</span><br><br> <div align=\"center\"><span style=\"color: #999999;\">Copyright &copy; 2020 Infinity DBX. All rights reserved.</span></div> <!--[if mso]> </div> <![endif]--><!--[if mso]> </font> <![endif]--> </div> </td> </tr> </table> <!--[if mso]> </div> </td> </tr> </center> </table> <![endif]--> </div> </div> </center> </body></html>','Online Banking application for your business accounts has been rejected','Infinity','dbx_cl@infinity.com',NULL,NULL,NULL);
INSERT INTO "emailtemplates" ("id", "TemplateName", "TemplateText", "Subject", "SenderName", "SenderEmail", "AlertChannel", "AlertLanguageCode", "Alert_id") VALUES (22,'ENROLLMENT_USERNAME_TEMPLATE','<p>&nbsp;</p><center><div style=\"width: 95%; height: 5px; margin: 0px 0px 0px 0px;\"><div><table border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\"><tbody><tr><td style=\"background-color: #284e77; font-size: 1px; line-height: 1px; -webkit-text-size-adjust: none;\" align=\"center\" valign=\"top\" bgcolor=\"#284e77\" height=\"10\">&nbsp;</td></tr></tbody></table></div></div><div style=\"width: 95%; margin: 0px 0px 50px 0px;\"><div style=\"display: inline-block; text-align: left;\"><table style=\"width: 50%;\" width=\"50%\"><tbody><tr><td width=\"200\"><img style=\"text-align: right; width: 200px; border: 0;\" src=\"https://retailbanking1.konycloud.com/dbimages/infinitydbxlogo.png\" alt=\"temenos_logo\" width=\"200\" /></td></tr></tbody></table> <br /><br />Hi %firstName% %lastName%,<br /><br />You are enrolled to Digital Banking Channel. Please activate your account now.<br /><br />%userName% is your username. Activation code is sent to you registered mobile number.<br /><br />You are required to input your username &amp; activation code in the link below.<br /><br /><div style=\"text-align: center; border-width: 1px; border-radius: 4px;\"><table style=\"table-layout: fixed;\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\"><tbody><tr><td style=\"color: #ffffff; background-color: #333b44; word-wrap: break-word; word-break: break-all; padding: 10px; line-height: 20px;\" align=\"center\"><div style=\"margin: 10px 10px 10px 10px; font-size: 13px;\">To activate your account and set a password,<a style=\"color: #11abeb;\" href=\"%resetPasswordLink%\">click here</a> <br />or paste the following link on your browser: <br /><br /><a style=\"color: #11abeb;\">%resetPasswordLink%</a></div></td></tr></tbody></table></div> <br /><center>The activation code will expire in %activationCodeExpiry% days , so activate it right away.</center><br /><br />Regards,<br />Temenos Banking Team <br /><br /><br /><br /><span style=\"color: #999999; font-size: 12px;\">This is a system generated mail. If you are not the named addressee please notify the sender immediately by e-mail at support@temenosbank.com and then delete the e-mail from your system. Although the company has taken reasonable precautions to ensure no viruses are present in this email, the company cannot accept responsibility for any loss or damage arising from the use of this email or attachments. Temenos, Inc. www.temenos.com </span><br /><br /><div align=\"center\"><span style=\"color: #999999;\"><strong>(c) Copyright Infinity Retail Origination</strong>. All rights reserved.</span></div></div></div></center>','Account Activation','Infinity','dbx_cl@infinity.com',NULL,NULL,NULL);
