INSERT INTO "notification" ("notificationId", "notificationModule", "notificationSubModule", "notificationSubject", "notificationText", "notificationActionLink", "notificationCategory", "actionButtonLabelName", "imageURL", "isRead", "receivedDate", "user") VALUES (15,'Account','Account','Giving You Motivation For Your Renovation!','<html><Body><p>No collateral is required, and the loan amount lets you tackle the projects without tapping into your homes equity. Not only do the interest rates start out lower than most average credit cards as low as 8.49%, we will even discount your APR* by 1.50%!  Up to 0.75% APR discount is provided based on length of the homeownership!</p></body></html>',NULL,NULL,NULL,'http://www.livemint.com/rf/Image-621x414/LiveMint/Period2/2016/12/27/Photos/Processed/HomeLoan-kMUG--621x414@LiveMint.jpg','0','2021-05-19 13:11:24',NULL);
