INSERT INTO "termandconditiontext" ("id", "TermAndConditionId", "LanguageCode", "Version_Id", "Description", "Content", "ContentType_id", "ContentModifiedBy", "ContentModifiedOn", "Status_id", "createdby", "modifiedby", "createdts", "lastmodifiedts", "synctimestamp", "softdeleteflag") VALUES ('3450031','1920031','en-US','1.0','Funding dislaimer - Acknowledgement page','Auto approval of the application does not guarantee the creation of an account. When account gets created, we will send an acknowledgement mail to you.','TEXT','Kony User','2021-05-19 07:42:42','SID_TANDC_ACTIVE',NULL,NULL,'2021-05-19 07:42:42','2021-05-19 07:42:42','2021-05-19 07:42:42',0);
INSERT INTO "termandconditiontext" ("id", "TermAndConditionId", "LanguageCode", "Version_Id", "Description", "Content", "ContentType_id", "ContentModifiedBy", "ContentModifiedOn", "Status_id", "createdby", "modifiedby", "createdts", "lastmodifiedts", "synctimestamp", "softdeleteflag") VALUES ('3450032','1920032','en-US','1.0','ID Scan disclaimer','The scan your ID document retrieves information used only on the context of this application. The bank stores the scanned document as a proof of identity and in accordance to local regulations.','TEXT','Kony User','2021-05-19 07:42:42','SID_TANDC_ACTIVE',NULL,NULL,'2021-05-19 07:42:42','2021-05-19 07:42:42','2021-05-19 07:42:42',0);
INSERT INTO "termandconditiontext" ("id", "TermAndConditionId", "LanguageCode", "Version_Id", "Description", "Content", "ContentType_id", "ContentModifiedBy", "ContentModifiedOn", "Status_id", "createdby", "modifiedby", "createdts", "lastmodifiedts", "synctimestamp", "softdeleteflag") VALUES ('3450033','1920033','en-US','1.0','Product Dasboard disclaimer','Investing involves risks, and there is always the potential of losing money when you invest in securities. You should review any planned financial transactions that may have tax or legal implications with your personal tax or legal advisor.','TEXT','Kony User','2021-05-19 07:42:42','SID_TANDC_ACTIVE',NULL,NULL,'2021-05-19 07:42:42','2021-05-19 07:42:42','2021-05-19 07:42:42',0);
