INSERT INTO "termandconditiontext" ("id", "TermAndConditionId", "LanguageCode", "Version_Id", "Description", "Content", "ContentType_id", "ContentModifiedBy", "ContentModifiedOn", "Status_id", "createdby", "modifiedby", "createdts", "lastmodifiedts", "synctimestamp", "softdeleteflag") VALUES ('3450036','1920029','es-ES','1.0','Funding dislaimer - Payment Type & Funding OTP pages','Puede optar por transferir fondos para su cuenta utilizando una cuenta con Banco Infinity o una cuenta de un banco distinto. Tendrᠱue autenticarse una vez que cree su cuenta en nuestro registro, por lo que usaremos para transferir fondos para su cuenta(s).','TEXT','Kony User','2021-05-19 07:42:42','SID_TANDC_ACTIVE',NULL,NULL,'2021-05-19 07:42:42','2021-05-19 07:42:42','2021-05-19 07:42:42',0);
