INSERT INTO "termandconditiontext" ("id", "TermAndConditionId", "LanguageCode", "Version_Id", "Description", "Content", "ContentType_id", "ContentModifiedBy", "ContentModifiedOn", "Status_id", "createdby", "modifiedby", "createdts", "lastmodifiedts", "synctimestamp", "softdeleteflag") VALUES ('3450039','1920030','fr-FR','1.0','Funding dislaimer - Existing & Manual Account Details pages',' Tous les comptes ne sont pas admissibles au transfert de fonds.\n Transfert de fonds effectu頰ar le biais des services bancaires en ligne Infinity avant que lheure limite dun jour ouvrable ne soit affich饠sur votre compte admissible le mꭥ jour. Le traitement des transactions par carte de cr餩t, de marge de cr餩t et dhypoth豵e peut prendre jusqu࠳ jours ouvrables, mais il sera affich頠 la date de lop鲡tion.','TEXT','Kony User','2021-05-19 07:42:42','SID_TANDC_ACTIVE',NULL,NULL,'2021-05-19 07:42:42','2021-05-19 07:42:42','2021-05-19 07:42:42',0);
