INSERT INTO "termandconditiontext" ("id", "TermAndConditionId", "LanguageCode", "Version_Id", "Description", "Content", "ContentType_id", "ContentModifiedBy", "ContentModifiedOn", "Status_id", "createdby", "modifiedby", "createdts", "lastmodifiedts", "synctimestamp", "softdeleteflag") VALUES ('3450041','1920031','fr-FR','1.0','Funding dislaimer - Acknowledgement page','Lapprobation automatique de la demande ne garantit pas la cr顴ion dun compte. Lorsque le compte est cr马 nous vous envoyons un courrier de remerciement','TEXT','Kony User','2021-05-19 07:42:42','SID_TANDC_ACTIVE',NULL,NULL,'2021-05-19 07:42:42','2021-05-19 07:42:42','2021-05-19 07:42:42',0);
INSERT INTO "termandconditiontext" ("id", "TermAndConditionId", "LanguageCode", "Version_Id", "Description", "Content", "ContentType_id", "ContentModifiedBy", "ContentModifiedOn", "Status_id", "createdby", "modifiedby", "createdts", "lastmodifiedts", "synctimestamp", "softdeleteflag") VALUES ('3450042','1920034','en-US','1.0','OFAC disclaimer for Personal Info page','To Help the government fight the funding of terrorism and money laundering activites, Federal law requires all financial institutions to obtain, verify and record information that identifies each person who opens an account. In the same instances, we may use outside sources to confirm the information provided by you. The information you provide is protected by our privacy policy and Federal Law.What this means for you: by clicking continue, you authorize us to collect your name, address, date of birth, ID and other information that will allow us to identify you.','TEXT','Kony User','2021-05-19 07:42:42','SID_TANDC_ACTIVE',NULL,NULL,'2021-05-19 07:42:42','2021-05-19 07:42:42','2021-05-19 07:42:42',0);
INSERT INTO "termandconditiontext" ("id", "TermAndConditionId", "LanguageCode", "Version_Id", "Description", "Content", "ContentType_id", "ContentModifiedBy", "ContentModifiedOn", "Status_id", "createdby", "modifiedby", "createdts", "lastmodifiedts", "synctimestamp", "softdeleteflag") VALUES ('3450043','1920035','en-US','1.0','Resume - Update Temporary password',' It should be between 8-16 characters length.\n It should be a combination of alphanumeric.\n No special characters and spaces are allowed.\n You can not choose your username as password.','TEXT','Kony User','2021-05-19 07:42:43','SID_TANDC_ACTIVE',NULL,NULL,'2021-05-19 07:42:43','2021-05-19 07:42:43','2021-05-19 07:42:43',0);
